Here's a complete Account Settings screen for React Native (TypeScript), designed to work correctly on both iOS and Android:

```tsx
import React, { useState } from 'react';
import {
  Alert,
  Platform,
  SafeAreaView,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TouchableOpacity,
  View,
  useColorScheme,
} from 'react-native';

// 48dp/pt meets Android's 48dp floor and clears iOS's 44pt floor.
const MIN_TARGET = 48;

type ToggleRow = {
  key: string;
  type: 'toggle';
  label: string;
  value: boolean;
  onToggle: (value: boolean) => void;
};

type NavRow = {
  key: string;
  type: 'nav';
  label: string;
  value?: string;
  onPress: () => void;
};

type SettingsRow = ToggleRow | NavRow;

type ColorScheme = typeof lightColors;

function AccountSettingsScreen() {
  const scheme = useColorScheme();
  const colors = scheme === 'dark' ? darkColors : lightColors;

  const [pushEnabled, setPushEnabled] = useState(true);
  const [biometricsEnabled, setBiometricsEnabled] = useState(false);

  const rows: SettingsRow[] = [
    {
      key: 'notifications',
      type: 'toggle',
      label: 'Push notifications',
      value: pushEnabled,
      onToggle: setPushEnabled,
    },
    {
      key: 'biometrics',
      type: 'toggle',
      label: Platform.OS === 'ios' ? 'Face ID & Passcode' : 'Fingerprint unlock',
      value: biometricsEnabled,
      onToggle: setBiometricsEnabled,
    },
    { key: 'privacy', type: 'nav', label: 'Privacy', onPress: () => {} },
    { key: 'language', type: 'nav', label: 'Language', value: 'English', onPress: () => {} },
    {
      key: 'appearance',
      type: 'nav',
      label: 'Appearance',
      value: scheme === 'dark' ? 'Dark' : 'Light',
      onPress: () => {},
    },
    { key: 'help', type: 'nav', label: 'Help & feedback', onPress: () => {} },
  ];

  const handleSignOut = () => {
    Alert.alert('Sign out?', 'You can sign back in anytime.', [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Sign out', onPress: () => {} },
    ]);
  };

  const handleDeleteAccount = () => {
    Alert.alert(
      'Delete account?',
      "This permanently removes your profile, data and settings. This can't be undone.",
      [
        { text: 'Cancel', style: 'cancel' },
        { text: 'Delete', style: 'destructive', onPress: confirmDelete },
      ],
    );
  };

  const confirmDelete = () => {
    // Call the delete-account API here.
  };

  return (
    <SafeAreaView style={[styles.safeArea, { backgroundColor: colors.background }]}>
      <ScrollView
        contentInsetAdjustmentBehavior="automatic"
        contentContainerStyle={styles.scrollContent}
      >
        <TouchableOpacity
          accessibilityRole="button"
          accessibilityLabel="Edit profile"
          style={[
            styles.profileRow,
            { backgroundColor: colors.surfaceContainer, minHeight: MIN_TARGET + 16 },
          ]}
          onPress={() => {}}
          activeOpacity={0.7}
        >
          <View style={[styles.avatar, { backgroundColor: colors.accent }]}>
            <Text style={styles.avatarText}>JD</Text>
          </View>
          <View style={styles.profileText}>
            <Text style={[styles.profileName, { color: colors.onSurface }]} numberOfLines={1}>
              Jordan Diaz
            </Text>
            <Text
              style={[styles.profileEmail, { color: colors.onSurfaceVariant }]}
              numberOfLines={1}
            >
              jordan.diaz@example.com
            </Text>
          </View>
          <Text style={[styles.chevron, { color: colors.onSurfaceVariant }]}>›</Text>
        </TouchableOpacity>

        <Text style={[styles.sectionLabel, { color: colors.onSurfaceVariant }]}>SETTINGS</Text>
        <View style={[styles.card, { backgroundColor: colors.surfaceContainer }]}>
          {rows.map((row, index) => (
            <SettingsRowItem
              key={row.key}
              row={row}
              colors={colors}
              isLast={index === rows.length - 1}
            />
          ))}
        </View>

        <Text style={[styles.sectionLabel, { color: colors.onSurfaceVariant }]}>ACCOUNT</Text>
        <View style={[styles.card, { backgroundColor: colors.surfaceContainer }]}>
          <TouchableOpacity
            accessibilityRole="button"
            style={[
              styles.row,
              { minHeight: MIN_TARGET, borderBottomWidth: 1, borderBottomColor: colors.divider },
            ]}
            onPress={handleSignOut}
            activeOpacity={0.7}
          >
            <Text style={[styles.rowLabel, { color: colors.onSurface }]}>Sign out</Text>
          </TouchableOpacity>

          <TouchableOpacity
            accessibilityRole="button"
            accessibilityLabel="Delete account"
            style={[styles.row, { minHeight: MIN_TARGET }]}
            onPress={handleDeleteAccount}
            activeOpacity={0.7}
          >
            <Text style={[styles.rowLabel, { color: colors.destructive, fontWeight: '500' }]}>
              Delete account
            </Text>
          </TouchableOpacity>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

function SettingsRowItem({
  row,
  colors,
  isLast,
}: {
  row: SettingsRow;
  colors: ColorScheme;
  isLast: boolean;
}) {
  const rowStyle = [
    styles.row,
    { minHeight: MIN_TARGET },
    !isLast && { borderBottomWidth: 1, borderBottomColor: colors.divider },
  ];

  if (row.type === 'toggle') {
    return (
      <View style={rowStyle}>
        <Text style={[styles.rowLabel, { color: colors.onSurface }]}>{row.label}</Text>
        <Switch
          value={row.value}
          onValueChange={row.onToggle}
          accessibilityLabel={row.label}
          accessibilityRole="switch"
        />
      </View>
    );
  }

  return (
    <TouchableOpacity
      style={rowStyle}
      onPress={row.onPress}
      activeOpacity={0.7}
      accessibilityRole="button"
      accessibilityLabel={row.label}
    >
      <Text style={[styles.rowLabel, { color: colors.onSurface }]}>{row.label}</Text>
      <View style={styles.rowRight}>
        {row.value ? (
          <Text style={[styles.rowValue, { color: colors.onSurfaceVariant }]}>{row.value}</Text>
        ) : null}
        <Text style={[styles.chevron, { color: colors.onSurfaceVariant }]}>›</Text>
      </View>
    </TouchableOpacity>
  );
}

const lightColors = {
  background: '#F2F2F7',
  surfaceContainer: '#FFFFFF',
  onSurface: '#1C1C1E',
  onSurfaceVariant: '#6E6E73',
  divider: '#E5E5EA',
  accent: '#0A84FF',
  destructive: '#FF3B30',
};

const darkColors = {
  background: '#000000',
  surfaceContainer: '#1C1C1E',
  onSurface: '#FFFFFF',
  onSurfaceVariant: '#9B9B9F',
  divider: '#2C2C2E',
  accent: '#0A84FF',
  destructive: '#FF453A',
};

const styles = StyleSheet.create({
  safeArea: { flex: 1 },
  scrollContent: { padding: 16, paddingBottom: 48 },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 14,
    paddingHorizontal: 16,
    marginBottom: 24,
  },
  avatar: {
    width: 48,
    height: 48,
    borderRadius: 24,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 12,
  },
  avatarText: { color: '#FFFFFF', fontWeight: '600', fontSize: 16 },
  profileText: { flex: 1 },
  profileName: { fontSize: 17, fontWeight: '600' },
  profileEmail: { fontSize: 13, marginTop: 2 },
  sectionLabel: {
    fontSize: 12,
    fontWeight: '600',
    letterSpacing: 0.4,
    marginBottom: 8,
    marginLeft: 4,
    textTransform: 'uppercase',
  },
  card: {
    borderRadius: 14,
    marginBottom: 24,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  rowLabel: { fontSize: 16, flexShrink: 1 },
  rowRight: { flexDirection: 'row', alignItems: 'center' },
  rowValue: { fontSize: 15, marginRight: 6 },
  chevron: { fontSize: 20, marginLeft: 2 },
});

export default AccountSettingsScreen;
```

Design notes:
- **Touch targets** are `minHeight: 48`, which clears both iOS's 44pt floor and Android's 48dp floor rather than tuning per platform.
- **Delete confirmation** uses the native `Alert.alert` with a destructive-styled button and a separate `Cancel` — on iOS it renders with the destructive red style, on Android it's a two-action Material dialog, so no platform branching is needed for the confirm step itself.
- **Safe areas / edge-to-edge** are handled by `SafeAreaView` + `contentInsetAdjustmentBehavior="automatic"`, so content never sits under the status bar, notch, or home indicator/gesture area on either OS.
- **Dark mode** uses `useColorScheme` with a light/dark token set rather than hardcoded colors, since both HIG and Material 3 expect dark-mode-aware surfaces.
- **Biometric row label** branches on `Platform.OS` since the feature name itself differs (Face ID vs. fingerprint), not the layout.
- No custom back button is included — this assumes the screen is pushed inside your existing navigator (e.g., React Navigation), which already supplies the platform-correct back affordance (leading button + edge-swipe on iOS, back gesture/button on Android); adding a second one would violate both platforms' back-navigation rules.
- Rows use plain `TouchableOpacity`/`Switch` from core RN only — no icon or navigation library assumed — so you can drop this directly into a screen component and wire `onPress`/`onToggle` handlers to your navigation and state logic.
